// CREDENTIAL, ...); the words stay identifiers, as the one-word class
// was, so a securable named like a class word is unaffected. Shared by
// GRANT/DENY/REVOKE, ALTER AUTHORIZATION and ALTER SCHEMA TRANSFER.
_securable_class: ($) =>
  seq($.identifier, optional(seq($.identifier, optional($.identifier))), '::'),

// The column list is aliased to a named `list` node (the same pattern

  ),

// tsgk P2-05: RESAMPLE [ON PARTITIONS (n [TO m] [, ...])] among the options.
_statistics_with_clause: ($) =>
  seq(
    $.keyword_with,
    comma_list(choice($.option, alias($._partitioned_option, $.option)), true),
  ),

// T-SQL table hint, e.g. WITH (NOLOCK), WITH (READUNCOMMITTED, INDEX(ix1)).

// tsgk P2-96: INSERT INTO OPENQUERY(...) | OPENROWSET(...) — keywords, so
// they cannot be read as a table with a column list.
choice(write_target($, { allowBareHint: false }), alias($._insert_rowset_target, $.invocation)),

// tsgk P2-08: EXTERNAL NAME assembly.class.method — the body of a SQLCLR
// module (procedure, function, trigger, aggregate, type).
external_name: ($) => seq($.keyword_external, $.keyword_name, field('name', $.object_reference)),

// EXECUTE AS { CALLER | SELF | OWNER | 'user_name' } — the module-level

      // tsgk P2-59: FROM EXECUTABLE FILE = 'path'
      seq($.keyword_executable, $.option),
    ),
  ),

// ACTIVE FOR BEGIN_DIALOG = { ON | OFF }

    // tsgk P2-80: [, mechanism ...]
    repeat(seq(',', $._key_encryptor_continuation)),
  ),

// DROP SYMMETRIC KEY name [REMOVE PROVIDER KEY]

// tsgk P2-99: the first operand may itself be a parenthesized set
// operation, `(SELECT ... UNION SELECT ...) INTERSECT (SELECT ...)`.
set_operation: ($) =>

operations.before:
// `SELECT ALL` is not accepted: ALL is also a unary operator
// (`= ALL (subquery)`), and `SELECT ALL x` is ambiguous between the two.
optional($.keyword_distinct),

operations.after:
// tsgk P2-101: SELECT ALL. ALL is also the unary quantifier (`= ALL
// (subquery)`), but a select item never starts with that quantifier, so
// the select-level reading wins by dynamic precedence.
optional(choice($.keyword_distinct, prec.dynamic(1, $.keyword_all))),

// tsgk P2-76: the plain `=` is an assignment too; a select item is never
// a bare comparison, so this reading wins by dynamic precedence.
choice(
  alias(choice('+=', '-=', '*=', '/=', '%=', '&=', '^=', '|=', '||='), $.assignment_operator),
  prec.dynamic(1, alias('=', $.assignment_operator)),
),

// tsgk P2-103: the first item is the mode (RAW | AUTO | EXPLICIT |
// PATH, or AUTO | PATH for JSON).
seq(
  $.keyword_xml,
  alias($._for_xml_mode, $.for_option),
  repeat(seq(',', $.for_option)),
),
seq(
  $.keyword_json,
  alias($._for_json_mode, $.for_option),
  repeat(seq(',', $.for_option)),
),

  seq($.keyword_read, $.keyword_only),
  // tsgk P2-40/P2-65: the ISO cursor's FOR READ_ONLY, and FOR BROWSE
  $.keyword_read_only,
  $.keyword_browse,
),

    ),
  ),

_for_xml_mode: ($) =>
  prec.right(
    seq(
      alias(choice($.keyword_raw, $.keyword_auto, $.keyword_explicit, $.keyword_path), $.identifier),
      optional(wrapped_in_parenthesis(optional($.literal))),
      repeat($.identifier),
    ),
  ),

_for_json_mode: ($) =>
  prec.right(
    seq(
      alias(choice($.keyword_auto, $.keyword_path), $.identifier),
      repeat($.identifier),
    ),
  ),

for_option: ($) =>

// tsgk P2-29: MAX_GRANT_PERCENT = n and USE PLAN N'xml'
optional(
  choice(
    paren_list($.literal, true),
    seq('=', $.literal),
    alias($._single_quote_string, $.literal),
  ),
),

      // tsgk P2-29: TABLE HINT (exposed_object_name [, table_hint [, ...]])
      seq(
        $.keyword_table,
        $.keyword_hint,
        wrapped_in_parenthesis(seq($.object_reference, repeat(seq(',', $.table_hint_item)))),
      ),
      // tsgk P2-29: FOR TIMESTAMP AS OF 'point_in_time'
      seq($.keyword_for, $.keyword_timestamp, $.keyword_as, $.keyword_of, $.literal),
    ),
  ),

optimize_for_item: ($) =>

  // tsgk P2-48/P2-90: OPENROWSET, OPENXML and PREDICT with their WITH
  // schema inside the relation.
  seq(
    alias($._rowset_invocation, $.invocation),
    optional(alias($._rowset_schema, $.openjson_schema)),
  ),
  // tsgk P2-85: composable DML, (DELETE | UPDATE | INSERT ... OUTPUT ...) AS d
  alias($._dml_table_source, $.subquery),
  // tsgk P2-74: a parenthesized joined table as a join operand
  wrapped_in_parenthesis(
    seq($._relation_with_hint, repeat1(choice($.join, $.cross_join, $.apply_join))),
  ),
),
// FOR SYSTEM_TIME sits between the table reference and its alias

// tsgk P2-67: FOR PATH marks a node or edge table of SHORTEST_PATH
optional($.keyword_for_path),
aliased_with_columns($),
// The deprecated bare hint sits inside `relation` rather than beside

_dml_table_source: ($) => wrapped_in_parenthesis(choice($.delete, $.update, $.insert)),

// tsgk P2-48/P2-73: OPENROWSET, OPENXML and PREDICT keep the invocation
// shape (their arguments are the same terms as before); naming them lets
// their WITH schema and alias stay inside `relation`. An argument may be
// `;`-separated, as OPENROWSET's 'datasource'; 'user_id'; 'password' is.
_rowset_invocation: ($) =>
  seq(
    alias($._rowset_function_name, $.object_reference),
    paren_list(seq(field('parameter', $.term), repeat(seq(';', field('parameter', $.term)))), true),
  ),

_rowset_function_name: ($) =>
  field('name', alias(choice($.keyword_openrowset, $.keyword_openxml, $.keyword_predict), $.identifier)),

// WITH (column type [COLLATE c] ['path' | ordinal] [NULL | NOT NULL] [, ...]) | WITH table_name
_rowset_schema: ($) =>
  seq($.keyword_with, choice(paren_list($.openjson_column, true), field('table', $.object_reference))),

// OPENDATASOURCE('provider', 'init string').database.schema.name — the

// tsgk P2-90: OPENROWSET / OPENXML / PREDICT columns may add COLLATE and
// nullability; OPENROWSET(BULK ...) takes a column ordinal in the path slot.
openjson_column: ($) =>

// tsgk P2-09: CREATE | ALTER BROKER PRIORITY name FOR CONVERSATION [SET (option [, ...])]
function broker_priority($, verb) {
  return prec.right(
    seq(
      verb,
      $.keyword_broker,
      $.keyword_priority,
      field('name', $.identifier),
      $.keyword_for,
      $.keyword_conversation,
      optional(seq($.keyword_set, paren_list($.option, true))),
    ),
  );
}

